def investigate(context, acquire):
    hist = acquire("history")

    def simulate(put_mode, trigger, channel_mode, actions):
        items = {}
        main_total = 0
        other_total = 0
        last_changes = 0
        tx = {"main": None, "other": None}
        tx_log = {"main": 0, "other": 0}

        def apply_write(conn, key, value, mode):
            nonlocal main_total, other_total, last_changes
            if tx[conn] is not None:
                cur = tx[conn]
            else:
                cur = items
            existed = key in cur
            old = cur.get(key)
            if mode == "put":
                if put_mode == "ignore":
                    if existed:
                        changed = 0
                    else:
                        cur[key] = value
                        changed = 1
                elif put_mode == "replace":
                    cur[key] = value
                    changed = 1
                else:
                    if existed:
                        if old == value:
                            changed = 0
                        else:
                            cur[key] = value
                            changed = 1
                    else:
                        cur[key] = value
                        changed = 1
            elif mode == "update":
                if existed:
                    if old == value:
                        changed = 0
                    else:
                        cur[key] = value
                        changed = 1
                else:
                    changed = 0
            elif mode == "delete":
                if existed:
                    del cur[key]
                    changed = 1
                else:
                    changed = 0
            else:
                changed = 0
            trig = 0
            if trigger and changed == 1 and mode == "put" and not existed:
                trig = 1
            if conn == "main":
                main_total += changed
                last_changes = changed
            else:
                other_total += changed
            if tx[conn] is not None:
                tx_log[conn] += trig
            return changed

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "begin":
                if tx[conn] is None:
                    tx[conn] = dict(items)
                    tx_log[conn] = 0
            elif op == "commit":
                if tx[conn] is not None:
                    items = tx[conn]
                    tx[conn] = None
                    tx_log[conn] = 0
            elif op == "rollback":
                if tx[conn] is not None:
                    tx[conn] = None
                    tx_log[conn] = 0
            elif op in ("put", "update", "delete"):
                key = act.get("key")
                value = act.get("value", 0)
                apply_write(conn, key, value, op)
        if channel_mode == "changes":
            ch = last_changes
        elif channel_mode == "total_changes":
            ch = main_total
        else:
            ch = main_total + other_total
        return ch, len(items), sum(items.values())

    put_modes = ["ignore", "replace", "upsert"]
    triggers = [False, True]
    channels = ["changes", "total_changes", "total_changes_both"]

    candidates = []
    for pm in put_modes:
        for tr in triggers:
            for ch in channels:
                ok = True
                for rec in hist:
                    acts = rec.get("actions", [])
                    obs = rec.get("observed", {})
                    c, cnt, sm = simulate(pm, tr, ch, acts)
                    if c != obs.get("channel") or cnt != obs.get("committed_count") or sm != obs.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    candidates.append((pm, tr, ch))

    goal = context.get("goal")
    actions = context.get("actions", [])
    vals = set()
    for pm, tr, ch in candidates:
        c, cnt, sm = simulate(pm, tr, ch, actions)
        if goal == "channel":
            vals.add(c)
        elif goal == "committed_count":
            vals.add(cnt)
        elif goal == "committed_sum":
            vals.add(sm)
        else:
            return {"value": None, "unresolved": True}
    if len(vals) == 1:
        return {"value": list(vals)[0], "unresolved": False}
    return {"value": None, "unresolved": True}
